import ast, json, pathlib

root = pathlib.Path(".")
rows = []
for p in sorted(root.joinpath("repo").rglob("*.py")):
    src = p.read_text(encoding="utf-8")
    tree = ast.parse(src)
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            n = node.end_lineno - node.lineno + 1
            if n > 30:
                rows.append({"file": p.as_posix(), "name": node.name, "lines": n})

pathlib.Path("audit.json").write_text(json.dumps(rows, indent=2) + "\n", encoding="utf-8")
print(len(rows))

